const raw = $input.item.json.output || '';
const marker = 'STATE:';
const idx = raw.indexOf(marker);

let replyText = raw;
let state = null;

if (idx !== -1) {
  replyText = raw.slice(0, idx).trim();
  const jsonPart = raw.slice(idx + marker.length).trim();
  try {
    state = JSON.parse(jsonPart);
  } catch (e) {
    state = null;
  }
}

const REAL_PRINTER_MODELS = [
  'Epson L120', 'Epson L121', 'Epson L130', 'Epson L360', 'Epson LX-310',
  'Epson L3110', 'Epson L3156', 'Epson L3210', 'Epson L3250', 'Epson L565',
  'Epson L5290', 'Epson L5590', 'Epson M3170', 'Epson L6370', 'Epson L6460',
  'Epson C5790', 'Epson L14150', 'Epson C5890', 'Epson L6550', 'Epson L15150',
  'Brother MFC T4500 DW'
];

function isValidEmail(v) {
  return typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim());
}

const validUsageLevels = ['Light', 'Moderate', 'Heavy', 'Very Heavy'];

let isReallyReady = false;
let rejectionReason = null;

if (state) {
  const hasBasicFields = Boolean(
    state.companyName && String(state.companyName).trim() &&
    state.companyAddress && String(state.companyAddress).trim() &&
    state.contactNumber && String(state.contactNumber).trim() &&
    isValidEmail(state.email) &&
    Array.isArray(state.purposes) && state.purposes.length > 0 &&
    validUsageLevels.includes(state.usageLevel) &&
    Number.isInteger(state.printerCount) && state.printerCount >= 1 &&
    Number.isInteger(state.rentalYears) && state.rentalYears >= 1 &&
    Array.isArray(state.printers) && state.printers.length > 0 &&
    state.printers.every(
      p => p.model && Number.isInteger(p.quantity) && p.quantity >= 1
    ) &&
    state.readyToSubmit === true
  );

  if (hasBasicFields) {
    const unknownModels = state.printers
      .map(p => p.model)
      .filter(m => !REAL_PRINTER_MODELS.includes(m));

    if (unknownModels.length > 0) {
      isReallyReady = false;
      rejectionReason = `I don't recognize "${unknownModels.join('", "')}" as one of our printer models. Could you double check the exact model name? We offer: ${REAL_PRINTER_MODELS.join(', ')}.`;
    } else {
      isReallyReady = true;
    }
  }
}

return {
  json: {
    reply: rejectionReason || replyText,
    state,
    isReallyReady
  }
};
